WITH eligible AS (SELECT s.* FROM sessions s WHERE EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.event_time < s.started_at)) SELECT s.id, s.customer_id, s.device, s.started_at, CASE WHEN device RLIKE '^(tablet|desktop)$' THEN 'CORE' WHEN device RLIKE '^(mobile)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS device_zone, (SELECT AVG(t2.discount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS avg_order_discount FROM eligible s ORDER BY device DESC NULLS FIRST;
